mapper.select:
select id, audit_no as auditNo, biz_module as bizModule, tournament_id as tournamentId,
       season_id as seasonId, object_type as objectType, object_id as objectId, biz_no as bizNo,
       action_type as actionType, action_result as actionResult, change_summary as changeSummary,
       action_reason as actionReason, operator_id as operatorId, operator_name as operatorName,
       create_time as createTime
from basket_business_audit
where is_delete = 0
and biz_module = #{bizModule}
and tournament_id = #{tournamentId}
and season_id = #{seasonId}
and object_type = #{objectType}
and object_id = #{objectId}
and action_type = #{actionType}
and operator_id = #{operatorId}

    and (audit_no like concat('%', #{keyword}, '%') or change_summary like concat('%', #{keyword}, '%'))

order by create_time desc, id desc
